async function uploadPrivateFile(file){
 const data=new FormData();
 data.append('file',file);
 data.append('is_private','1');
 const response=await fetch('/api/method/upload_file',{method:'POST',credentials:'same-origin',headers:{'X-Frappe-CSRF-Token':frappe.csrf_token||window.csrf_token||''},body:data});
 const result=await response.json();
 if(!response.ok||!result.message?.name)throw new Error('Upload failed. Please retry.');
 return result.message;
}

