const SchemeWorkspace = {
  props: { customer: String },
  setup(props) {
    const host = ref(null);
    let workspace;
    onMounted(() => {
      workspace = window.snrgSchemeWorkspace.mount(host.value, true, props.customer, (element, options) => {
        const value = ref(options.modelValue);
        const picker = createApp({
          render: () => h(DatePicker, {...options, modelValue: value.value,
            'onUpdate:modelValue': date => { value.value = date; }}),
        });
        picker.mount(element);
        return () => picker.unmount();
      });
    });
    onUnmounted(() => workspace?.unmountDates());
    return {host};
  },
  template: '<div ref="host"></div>',
};

